function DashboardCharts({payments,opportunities,currency}:{payments:R[];opportunities:R[];currency?:string}){const months=Array.from({length:6},(_,i)=>{const x=new Date();x.setDate(1);x.setMonth(x.getMonth()-(5-i));return x});const revenue=months.map(m=>{const key=m.getFullYear()+"-"+String(m.getMonth()+1).padStart(2,"0");return {label:m.toLocaleDateString("en-US",{month:"short"}),value:payments.filter(r=>{const dt=new Date(r.payment_date||r.created_at);return dt.getFullYear()+"-"+String(dt.getMonth()+1).padStart(2,"0")===key}).reduce((n:number,r:R)=>n+Number(r.amount||0),0)}});const max=Math.max(...revenue.map(x=>x.value),1);const points=revenue.map((x,i)=>({x:10+i*18,y:90-(x.value/max)*70}));const path=points.map((p,i)=>(i?"L":"M")+p.x+" "+p.y).join(" ");const stages=["discovery","qualified","proposal","negotiation"];const pipeline=stages.map(stage=>({stage,value:opportunities.filter(r=>r.stage===stage).reduce((n:number,r:R)=>n+Number(r.estimated_value||0),0)}));const pmax=Math.max(...pipeline.map(x=>x.value),1);return <div className="chart-grid"><section className="card chart-card"><div className="panel-head"><div><h3>Revenue trend</h3><small>Collected payments · last 6 months</small></div><span className="chart-unit">{currency||"EUR"}</span></div><div className="line-chart"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="Revenue trend"><path className="chart-gridline" d="M10 20H98M10 55H98M10 90H98"/><path className="chart-area" d={path+" L90 90 L10 90 Z"}/><path className="chart-line" d={path}/>{points.map((p,i)=><circle key={i} cx={p.x} cy={p.y} r="1.5" className="chart-dot"/>)}</svg><div className="chart-labels">{revenue.map(x=><span key={x.label}>{x.label}</span>)}</div></div><div className="chart-total"><span>6-month collected</span><b>{money(revenue.reduce((n,x)=>n+x.value,0),currency)}</b></div></section><section className="card chart-card"><div className="panel-head"><div><h3>Pipeline by stage</h3><small>Open opportunity value</small></div><span className="chart-unit">{currency||"EUR"}</span></div><div className="pipeline-chart">{pipeline.map(x=><div className="pipeline-row" key={x.stage}><div className="pipeline-meta"><span>{cap(x.stage)}</span><b>{money(x.value,currency)}</b></div><div className="pipeline-track"><i style={{width:(x.value/pmax*100)+"%"}}/></div></div>)}{!opportunities.length&&<Empty text="No open opportunities yet."/>}</div></section></div>}

